package com.bank.cache.cache;

import java.util.LinkedHashMap;
import java.util.Map;

// LRU by access order, plus a per-entry TTL for freshness.
public class LruTtlCache<K, V> {
    private static final class Entry<V> {
        final V value; final long expiresAt;
        Entry(V value, long expiresAt) { this.value = value; this.expiresAt = expiresAt; }
    }
    private final long ttlMillis;
    private final LinkedHashMap<K, Entry<V>> map;

    public LruTtlCache(int maxSize, long ttlMillis) {
        this.ttlMillis = ttlMillis;
        // accessOrder=true makes get() move the key to most-recently-used.
        this.map = new LinkedHashMap<>(16, 0.75f, true) {
            @Override protected boolean removeEldestEntry(Map.Entry<K, Entry<V>> eldest) {
                return size() > maxSize; // evict least-recently-used when over capacity
            }
        };
    }

    public V get(K key) {
        Entry<V> e = map.get(key);
        if (e == null) return null;
        if (System.currentTimeMillis() > e.expiresAt) { map.remove(key); return null; } // TTL expiry
        return e.value;
    }
    public void put(K key, V value) {
        map.put(key, new Entry<>(value, System.currentTimeMillis() + ttlMillis));
    }
    public int size() { return map.size(); }
}
