package com.bank.cache.service;

import com.bank.cache.cache.LruTtlCache;
import com.bank.cache.model.Account;
import com.bank.cache.repository.AccountRepository;
import java.math.BigDecimal;
import java.util.concurrent.atomic.AtomicLong;

// Cache-aside: check cache, on miss read DB and populate. Tracks hit rate.
public class BalanceService {
    private final AccountRepository repo;
    private final LruTtlCache<String, BigDecimal> cache;
    private final AtomicLong hits = new AtomicLong();
    private final AtomicLong misses = new AtomicLong();

    public BalanceService(AccountRepository repo, LruTtlCache<String, BigDecimal> cache) {
        this.repo = repo; this.cache = cache;
    }

    public BigDecimal getBalance(String accountId) {
        BigDecimal cached = cache.get(accountId);
        if (cached != null) { hits.incrementAndGet(); return cached; }
        misses.incrementAndGet();
        Account a = repo.findById(accountId); // the expensive hop we are trying to avoid
        if (a == null) return null;
        cache.put(accountId, a.getBalance());
        return a.getBalance();
    }
    public double hitRate() {
        long h = hits.get(), m = misses.get(), total = h + m;
        return total == 0 ? 0.0 : (double) h / total;
    }
    public long getMisses() { return misses.get(); }
}
