package com.bank.cache;

import com.bank.cache.cache.LruTtlCache;
import com.bank.cache.model.Account;
import com.bank.cache.repository.AccountRepository;
import com.bank.cache.service.BalanceService;
import java.math.BigDecimal;
import java.util.logging.*;

public class CacheEvictionDemo {
    private static final Logger log = Logger.getLogger(CacheEvictionDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }
    public static void main(String[] args) {
        AccountRepository repo = new AccountRepository();
        repo.seed(new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        repo.seed(new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
        for (int i = 1; i <= 8; i++)
            repo.seed(new Account("ACC" + i, "Customer " + i, new BigDecimal(1000 * i)));

        LruTtlCache<String, BigDecimal> cache = new LruTtlCache<>(4, 30_000);
        BalanceService svc = new BalanceService(repo, cache);

        // Realistic skew: Rajesh (SAV2001) is HOT, plus a scan of cold one-hit keys.
        for (int round = 0; round < 50; round++) {
            svc.getBalance("SAV2001");            // hot key, read every round
            svc.getBalance("ACC" + (round % 8 + 1)); // cold scan churns the cache
        }
        log.info(() -> "Hot key SAV2001 served; cache size=" + cache.size());
        log.info(() -> String.format("Hit rate=%.1f%% misses=%d (DB hops)",
                svc.hitRate() * 100, svc.getMisses()));
        if (svc.hitRate() < 0.5)
            log.warning("Hit rate below 50% — cache may be a NET NEGATIVE here");
    }
}

