package com.bank.cache.repository;

import com.bank.cache.model.Account;
import java.util.HashMap;
import java.util.Map;

// Simulated DB. Every findById is the "expensive hop" a cache tries to avoid.
public class AccountRepository {
    private final Map<String, Account> store = new HashMap<>();
    public void seed(Account a) { store.put(a.getAccountId(), a); }
    public Account findById(String id) {
        try { Thread.sleep(2); } catch (InterruptedException ignored) {} // simulate DB latency
        return store.get(id);
    }
}
